import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import {discoverJs,partition,timings} from '../../scripts/ci-shards.mjs';
import {shardLuaScripts} from '../../scripts/test-lua.mjs';
const hash=x=>createHash('sha256').update(x).digest('hex'),base='d8a57cae2a867200ca8e588abc0d368e6cdb3799';
const paths=execFileSync('git',['ls-tree','-r','--name-only',base],{encoding:'utf8'}).trim().split('\n');
const currentJs=discoverJs().sort(),currentLua=readdirSync('tests/lua').filter(n=>n.endsWith('.lua')).map(n=>'tests/lua/'+n).sort();
const baselineJs=paths.filter(p=>/^tests\/[^/]+\.test\.mjs$/.test(p)).sort(),baselineLua=paths.filter(p=>/^tests\/lua\/[^/]+\.lua$/.test(p)).sort();
const before=JSON.parse(execFileSync('git',['show',base+':scripts/ci-test-timings.json'],{encoding:'utf8'}));
function forecast(js,lua,timing){const result={inventory:{js:js.length,lua:lua.length}};
 for(const [platform,count,budget]of [['win32',17,1800000],['linux',13,1200000]]){
  const weights=Object.fromEntries(js.map(file=>[file,Math.max(timing.js[platform][file]??timing.unknownJsMs,timing.jsPlanning.localLowerBounds[file]?.durationMs??0)]));
  const initial=Array.from({length:count},(_,i)=>i?0:timing.initialMs[platform][0]);
  const plans=Array.from({length:count},(_,i)=>partition(js,`${i+1}/${count}`,weights,timing.unknownJsMs,initial));
  assert.deepEqual(plans.flatMap(p=>p.files).sort(),js);const loads=plans[0].loads;
  let combined=loads,rawCounts=null,rawFiles=null;
  if(platform==='win32'){
   const bins=Array.from({length:count},(_,i)=>shardLuaScripts(lua,`${i+1}/${count}`,{...timing,windowsJsShardMs:loads},2));
   assert.deepEqual(bins.flat().sort(),lua);rawCounts=bins.map(x=>x.length);rawFiles=bins;
   const cost=f=>timing.luaShard[f]??timing.lua[f]??timing.unknownLuaMs,safety=f=>timing.lua[f]??timing.unknownLuaMs;
   combined=bins.map((bin,i)=>{const pool=[0,0];for(const f of bin.filter(f=>safety(f)<10000).sort((a,b)=>safety(b)-safety(a)||a.localeCompare(b)))pool[pool[0]<=pool[1]?0:1]+=cost(f);return loads[i]+bin.filter(f=>safety(f)>=10000).reduce((n,f)=>n+cost(f),0)+Math.max(...pool);});
  }
  const maximumMs=Math.max(...combined);result[platform]={shards:count,jsFileCounts:plans.map(p=>p.files.length),rawFileCounts:rawCounts,jsFiles:plans.map(p=>p.files),rawFiles,jsLoadsMs:loads,combinedLoadsMs:combined,maximumMs,reserveMs:60000,maxPlusReserveMs:maximumMs+60000,budgetMs:budget,marginMs:budget-maximumMs-60000};
 }return result;}
const result={schemaVersion:1,kind:'CardUpgrade local scheduling forecast; not hosted execution',baseSha:base,qualityShapeSha256:hash(readFileSync('scripts/ci-quality-shape.mjs')),workflowSha256:hash(readFileSync('.github/workflows/quality.yml')),timingsSha256:hash(readFileSync('scripts/ci-test-timings.json')),shape:{windows:17,posix:13},reserveMs:60000,rawWorkers:2,concurrencyCap:12,budgetsMs:{windows:1800000,posix:1200000},inventory:{baselineJs,currentJs,baselineLua,currentLua,addedJs:currentJs.filter(p=>!baselineJs.includes(p)),addedLua:currentLua.filter(p=>!baselineLua.includes(p)),removedJs:baselineJs.filter(p=>!currentJs.includes(p)),removedLua:baselineLua.filter(p=>!currentLua.includes(p))},baseline:forecast(baselineJs,baselineLua,before),cardUpgradeInventoryBeforeFloor:forecast(currentJs,currentLua,before),cardUpgradeWithFloor:forecast(currentJs,currentLua,timings),limitations:['Only a placement estimate; #541 budget changes are not included.','POSIX estimate includes JS and initial engineering reservation, not a measured full hosted job.','Windows estimate includes JS then raw Lua with the unchanged two-worker/exclusive safety model.','No Full, hosted pass or merge readiness is asserted.']};
assert.deepEqual(result.inventory.addedJs,['tests/card-upgrade-ownership.test.mjs','tests/card-upgrade-source.test.mjs']);assert.deepEqual(result.inventory.addedLua,['tests/lua/card_upgrade_ownership_contract.lua']);assert.deepEqual(result.inventory.removedJs,[]);assert.deepEqual(result.inventory.removedLua,[]);
writeFileSync('docs/evidence/m7-card-upgrade-delivery-planning-20261107.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(Object.fromEntries(['baseline','cardUpgradeInventoryBeforeFloor','cardUpgradeWithFloor'].map(key=>[key,{inventory:result[key].inventory,windows:result[key].win32.maxPlusReserveMs,windowsMargin:result[key].win32.marginMs,posix:result[key].linux.maxPlusReserveMs,posixMargin:result[key].linux.marginMs}])),null,2));

import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const path='scripts/ci-test-timings.json',original=readFileSync(path),hash=x=>createHash('sha256').update(x).digest('hex');
const variants=[['delete-card-upgrade-floor',x=>delete x.jsPlanning.localLowerBounds['tests/card-upgrade-ownership.test.mjs']],['change-old-floor',x=>x.jsPlanning.localLowerBounds['tests/run-max-hp-config-inverse.test.mjs'].durationMs--],['change-hosted-weight',x=>x.js.win32['tests/act3-shapes.test.mjs']++],['change-metadata',x=>x.jsPlanning.localLowerBounds['tests/card-upgrade-ownership.test.mjs'].environment='hosted Linux']];
variants.push(['lower-new-floor',x=>x.jsPlanning.localLowerBounds['tests/card-upgrade-ownership.test.mjs'].durationMs--],['change-raw-safety',x=>x.lua[Object.keys(x.lua)[0]]++]);
const results=[];
try{
 for(const [name,change]of variants){const value=JSON.parse(original);change(value);const mutant=JSON.stringify(value,null,2)+'\n';writeFileSync(path,mutant);
  const args=['--test','--test-concurrency=1','--test-name-pattern=^CardUpgrade timing epoch appends','tests/ci-complete-calibration.test.mjs'];
  const started=performance.now();const result=spawnSync(process.execPath,args,{encoding:'utf8',env:{...process.env,TMPDIR:'/workspace/scratch/c1a4970a76e0/card-upgrade-delivery-tmp'}}),log=(result.stdout??'')+(result.stderr??'');
  writeFileSync(`build/card-upgrade-delivery/negative-${name}.log`,log);assert.equal(result.status,1);assert.match(log,/current CardUpgrade timing epoch requires/);assert.match(log,/fail 1/);
  results.push({name,command:['node',...args].join(' '),status:result.status,wallMs:performance.now()-started,signal:result.signal,error:result.error?.message??null,mutatedSourceSha256:hash(mutant),log:`build/card-upgrade-delivery/negative-${name}.log`,logSha256:hash(log),rejectedBy:'current CardUpgrade timing epoch requires the exact complete floor and unchanged prior values'});
 }
}finally{writeFileSync(path,original);assert.equal(hash(readFileSync(path)),hash(original));}
writeFileSync('build/card-upgrade-delivery/current-gate-negative.json',JSON.stringify({originalSha256:hash(original),restoredSha256:hash(readFileSync(path)),results},null,2)+'\n');
console.log(JSON.stringify(results.map(x=>({name:x.name,status:x.status})),null,2));
